class NewClientForm extends StatefulWidget {
  const NewClientForm({super.key, this.initialClient});

  final ClientDetail? initialClient;

  @override
  State<NewClientForm> createState() => _NewClientFormState();
}

class _NewClientFormState extends State<NewClientForm> {
  final _nameController = TextEditingController();
  final _ageController = TextEditingController();
  final _phoneController = TextEditingController();
  final _pinController = TextEditingController();
  final _memoController = TextEditingController();
  final _apiService = ApiService();
  String? _gender;
  bool _isSaving = false;
  bool _isPinObscured = true;

  bool get _isEditing => widget.initialClient != null;

  @override
  void initState() {
    super.initState();
    final client = widget.initialClient;
    if (client == null) return;
    _nameController.text = client.name;
    _ageController.text = client.age?.toString() ?? '';
    _phoneController.text = client.phone ?? '';
    _memoController.text = client.memo ?? '';
    _gender = client.gender;
  }

  @override
  void dispose() {
    _nameController.dispose();
    _ageController.dispose();
    _phoneController.dispose();
    _pinController.dispose();
    _memoController.dispose();
    super.dispose();
  }

  Future<void> _saveClient() async {
    if (_isSaving) return;

    final name = _nameController.text.trim();
    if (name.isEmpty) {
      _showMessage('이름을 입력해 주세요.');
      return;
    }

    final ageText = _ageController.text.trim();
    final age = ageText.isEmpty ? null : int.tryParse(ageText);
    if (ageText.isNotEmpty && (age == null || age < 0 || age > 130)) {
      _showMessage('나이는 0에서 130 사이의 숫자로 입력해 주세요.');
      return;
    }

    final phone = _phoneController.text.trim();
    if (phone.isEmpty) {
      _showMessage('내담자 로그인에 사용할 연락처를 입력해 주세요.');
      return;
    }

    final pin = _pinController.text.trim();
    if ((!_isEditing || pin.isNotEmpty) && !RegExp(r'^\d{6}$').hasMatch(pin)) {
      _showMessage(
        _isEditing
            ? '비밀번호를 변경하려면 숫자 6자리를 입력해 주세요.'
            : '초기 비밀번호는 숫자 6자리로 입력해 주세요.',
      );
      return;
    }

    setState(() => _isSaving = true);
    final memo = _memoController.text.trim();
    try {
      if (_isEditing) {
        await _apiService.updateClient(
          widget.initialClient!.id,
          name: name,
          age: age,
          gender: _gender,
          phone: phone,
          loginId: phone,
          pin: pin.isEmpty ? null : pin,
          memo: memo.isEmpty ? null : memo,
        );
      } else {
        await _apiService.createClient(
          name: name,
          age: age,
          gender: _gender,
          phone: phone,
          loginId: phone,
          pin: pin,
          memo: memo.isEmpty ? null : memo,
        );
      }
    } catch (error) {
      if (!mounted) return;
      setState(() => _isSaving = false);
      _showMessage(error.toString().replaceFirst('Exception: ', ''));
      return;
    }

    if (!mounted) return;
    setState(() => _isSaving = false);
    Navigator.of(context).pop(_isEditing ? '내담자 정보를 수정했습니다.' : '내담자를 등록했습니다.');
  }

  void _showMessage(String message) {
    ScaffoldMessenger.of(
      context,
    ).showSnackBar(SnackBar(content: Text(message)));
  }

  Widget _genderOption({required String value, required String label}) {
    final selected = _gender == value;
    return Expanded(
      child: InkWell(
        onTap: () => setState(() => _gender = value),
        borderRadius: BorderRadius.circular(12),
        child: Container(
          padding: const EdgeInsets.symmetric(vertical: 12),
          decoration: ShapeDecoration(
            color: selected ? const Color(0xFFFFF4F2) : Colors.white,
            shape: RoundedRectangleBorder(
              side: BorderSide(
                width: 1.5,
                color: selected
                    ? const Color(0xFFFF6B53)
                    : const Color(0xFFEAEFF2),
              ),
              borderRadius: BorderRadius.circular(12),
            ),
          ),
          child: Center(
            child: Text(
              label,
              style: TextStyle(
                color: selected
                    ? const Color(0xFFFF6B53)
                    : const Color(0xFF1A2B49),
                fontSize: 15,
                fontFamily: 'GowunBatang',
                fontWeight: selected ? FontWeight.w700 : FontWeight.w500,
              ),
            ),
          ),
        ),
      ),
    );
  }

